// Regenerates src/types/database.ts from the local Supabase database (npm run db:types).
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const header = `/**
 * Database types, generated by \`supabase gen types typescript\` from the migrations.
 * Do not edit by hand: regenerate with \`npm run db:types\` (or copy from the CI
 * "Generated database types" step) after changing a migration.
 */
`;
const generated = execSync("npx supabase gen types typescript", { encoding: "utf8" });
writeFileSync("src/types/database.ts", header + generated);
execSync("npx prettier --write src/types/database.ts", { stdio: "inherit" });
